svg.script:
console.log('[SVG Site Popup] Script executing');
(function () {
  function init() {
    var doc = document;
    var svg = doc.getElementById('svg1') || doc.querySelector('svg');
    if (!svg) {
      console.log('[SVG Site Popup] FAIL: SVG not found');
      return;
    }

    var tip = doc.getElementById('site-tooltip');
    var tooltipRect = doc.getElementById('tooltip-bg');
    var tooltipShadow = doc.getElementById('tooltip-shadow');
    var tooltipAccent = doc.getElementById('tooltip-accent');
    var siteNameText = doc.getElementById('tooltip-site-name');
    var telemetryText = doc.getElementById('tooltip-telemetry');
    var assetText = doc.getElementById('tooltip-asset');

    // Separate hover label: site name only. This remains independent of the
    // existing click popup so Asset Intellect telemetry publishing is unchanged.
    var hoverTip = doc.getElementById('hover-tooltip');
    var hoverTooltipRect = doc.getElementById('hover-tooltip-bg');
    var hoverSiteNameText = doc.getElementById('hover-tooltip-site-name');
    var hoverReady = !!(hoverTip && hoverTooltipRect && hoverSiteNameText);
    if (hoverReady) hoverTip.style.pointerEvents = 'none';

    // The status legend is display-only. Keep it outside the site selector and
    // swallow its pointer/click events so they cannot trigger map actions below it.
    var statusLegend = doc.getElementById('status-legend');
    function isStatusLegendElement(target) {
      return !!(statusLegend && target && (target === statusLegend || statusLegend.contains(target)));
    }

    if (!tip || !tooltipRect || !siteNameText || !telemetryText || !assetText) {
      console.log('[SVG Site Popup] FAIL: tooltip elements not found');
      return;
    }

    // Keep the tooltip visible/click-through friendly. It must never block clicks
    // intended for Asset Intellect site markers.
    tip.style.pointerEvents = 'none';

    var siteSelector = '.site-marker, .Site, circle[id^="site-"], rect[id^="site-"], path[id^="site-"], ellipse[id^="site-"], g[id^="site-"]';

    function findSiteElement(target) {
      if (isStatusLegendElement(target)) return null;
      if (!target || !target.closest) return null;
      var el = target.closest(siteSelector);
      if (!el || el.id === 'site-tooltip' || (tip && tip.contains(el))) return null;
      return el;
    }

    function makeSitesClickable() {
      var sites = doc.querySelectorAll(siteSelector);
      sites.forEach(function (site) {
        if (site.id === 'site-tooltip' || (tip && tip.contains(site))) return;
        site.style.cursor = 'pointer';
        site.style.pointerEvents = 'all';
        site.setAttribute('tabindex', '0');
        if (!site.getAttribute('role')) site.setAttribute('role', 'button');
      });
      console.log('[SVG Site Popup] clickable points ready: ' + sites.length);
    }

    makeSitesClickable();

    function getSvgPoint(evt) {
      var pt = svg.createSVGPoint();
      pt.x = evt.clientX || 0;
      pt.y = evt.clientY || 0;
      var ctm = svg.getScreenCTM();
      return ctm ? pt.matrixTransform(ctm.inverse()) : pt;
    }

    function positionTooltip(evt, el) {
      var pt;
      if (evt && typeof evt.clientX === 'number' && typeof evt.clientY === 'number') {
        pt = getSvgPoint(evt);
      } else {
        pt = {
          x: parseFloat(el.getAttribute('cx') || el.getAttribute('x') || '0'),
          y: parseFloat(el.getAttribute('cy') || el.getAttribute('y') || '0')
        };
      }

      var rectW = parseFloat(tooltipRect.getAttribute('width')) || 58;
      var rectH = parseFloat(tooltipRect.getAttribute('height')) || 15;
      var vb = svg.viewBox && svg.viewBox.baseVal;
      var maxX = vb && vb.width ? vb.width : parseFloat(svg.getAttribute('width')) || 222;
      var maxY = vb && vb.height ? vb.height : parseFloat(svg.getAttribute('height')) || 202;
      var offset = 2;

      var x = pt.x + offset;
      var y = pt.y - rectH - offset;

      if (x + rectW > maxX) x = pt.x - rectW - offset;
      if (y < 0) y = pt.y + offset;
      if (x < 0) x = 0;
      if (y < 0) y = 0;
      if (x + rectW > maxX) x = maxX - rectW;
      if (y + rectH > maxY) y = maxY - rectH;

      tip.setAttribute('transform', 'translate(' + x + ',' + y + ')');
    }

    // Displays only the site name while the pointer is over a marker. The
    // original click popup below is intentionally left as-is.
    function positionHoverTooltip(evt, el) {
      if (!hoverReady) return;

      var pt;
      if (evt && typeof evt.clientX === 'number' && typeof evt.clientY === 'number') {
        pt = getSvgPoint(evt);
      } else {
        pt = {
          x: parseFloat(el.getAttribute('cx') || el.getAttribute('x') || '0'),
          y: parseFloat(el.getAttribute('cy') || el.getAttribute('y') || '0')
        };
      }

      var rectW = parseFloat(hoverTooltipRect.getAttribute('width')) || 36;
      var rectH = parseFloat(hoverTooltipRect.getAttribute('height')) || 7;
      var vb = svg.viewBox && svg.viewBox.baseVal;
      var maxX = vb && vb.width ? vb.width : parseFloat(svg.getAttribute('width')) || 222;
      var maxY = vb && vb.height ? vb.height : parseFloat(svg.getAttribute('height')) || 202;
      var offset = 2;
      var x = pt.x + offset;
      var y = pt.y - rectH - offset;

      if (x + rectW > maxX) x = pt.x - rectW - offset;
      if (y < 0) y = pt.y + offset;
      if (x < 0) x = 0;
      if (y < 0) y = 0;
      if (x + rectW > maxX) x = maxX - rectW;
      if (y + rectH > maxY) y = maxY - rectH;

      hoverTip.setAttribute('transform', 'translate(' + x + ',' + y + ')');
    }

    function showHoverName(el, evt) {
      if (!hoverReady || !el) return;
      var siteName = el.getAttribute('data-site-name') || el.getAttribute('data-asset-id') || el.getAttribute('id') || 'Unknown site';
      hoverSiteNameText.textContent = siteName;

      var popupWidth = Math.max(24, Math.min(62, 5 + siteName.length * 1.75));
      hoverTooltipRect.setAttribute('width', popupWidth);
      hoverTip.setAttribute('visibility', 'visible');
      positionHoverTooltip(evt, el);
    }

    function hideHoverName() {
      if (hoverReady) hoverTip.setAttribute('visibility', 'hidden');
    }

    var selectedIndicator = doc.getElementById('selected-site-indicator');

    function updateSelectedIndicator(el) {
      if (!selectedIndicator) return;
      selectedIndicator.setAttribute('data-id-selected', el.getAttribute('id') || '');
      selectedIndicator.setAttribute('data-telemetry-id-selected', el.getAttribute('data-telemetry-id') || '');
      selectedIndicator.setAttribute('data-status-selected', el.getAttribute('data-status') || '');
      selectedIndicator.setAttribute('data-asset-id-selected', el.getAttribute('data-asset-id') || '');
      selectedIndicator.setAttribute('data-site-name-selected', el.getAttribute('data-site-name') || '');

      var cx = el.getAttribute('cx') || el.getAttribute('x');
      var cy = el.getAttribute('cy') || el.getAttribute('y');
      if (cx !== null) selectedIndicator.setAttribute('cx', cx);
      if (cy !== null) selectedIndicator.setAttribute('cy', cy);
      var r = parseFloat(el.getAttribute('r')) || 1;
      selectedIndicator.setAttribute('r', r + 1);
      selectedIndicator.setAttribute('visibility', 'visible');
    }

    function showSitePopup(el, evt) {
      // Do not stop propagation here: Asset Intellect needs the original click event
      // to read Interconnect="Selected" and publish data-telemetry-id.

      var siteName = el.getAttribute('data-site-name') || el.getAttribute('id') || 'Unknown site';
      var telemetryId = el.getAttribute('data-telemetry-id') || 'N/A';
      var assetId = el.getAttribute('data-asset-id') || 'N/A';

      siteNameText.textContent = siteName;
      telemetryText.textContent = 'Telemetry ID: ' + telemetryId;
      assetText.textContent = 'Asset ID: ' + assetId;

      var longest = Math.max(siteName.length, telemetryText.textContent.length, assetText.textContent.length);
      var popupWidth = Math.max(48, Math.min(72, 6 + longest * 1.8));
      tooltipRect.setAttribute('width', popupWidth);
      if (tooltipShadow) tooltipShadow.setAttribute('width', popupWidth);
      if (tooltipAccent) tooltipAccent.setAttribute('height', tooltipRect.getAttribute('height') || '15');

      tip.setAttribute('visibility', 'visible');
      positionTooltip(evt, el);
      updateSelectedIndicator(el);

      console.log('[SVG Site Popup] clicked', {
        site_name: siteName,
        tel_id: telemetryId,
        asset_id: assetId,
        point_id: el.getAttribute('id') || ''
      });
    }

    function hideTooltip(evt) {
      if (findSiteElement(evt && evt.target)) return;
      tip.setAttribute('visibility', 'hidden');
      if (selectedIndicator) selectedIndicator.setAttribute('visibility', 'hidden');
    }

    function handleSvgClick(evt) {
      if (isStatusLegendElement(evt.target)) {
        hideHoverName();
        evt.preventDefault();
        evt.stopImmediatePropagation();
        return;
      }
      var site = findSiteElement(evt.target);
      if (site) {
        // Let Asset Intellect receive the original click so it can publish
        // Interconnect=Selected and data-telemetry-id. Then redraw the popup
        // once more after any AI click processing has finished.
        showSitePopup(site, evt);
        window.setTimeout(function () {
          showSitePopup(site, evt);
        }, 0);
      } else {
        hideTooltip(evt);
      }
    }

    // Site-name-only hover label. Pointer events are observed without stopping
    // propagation, so existing click/reset/interconnect behaviour remains intact.
    svg.addEventListener('pointermove', function (evt) {
      if (isStatusLegendElement(evt.target)) {
        hideHoverName();
        return;
      }
      var site = findSiteElement(evt.target);
      if (site) {
        showHoverName(site, evt);
      } else {
        hideHoverName();
      }
    }, true);

    svg.addEventListener('pointerleave', hideHoverName, true);

    // Capture phase makes the SVG popup run before host-page handlers.
    // Not stopping propagation keeps telemetry publishing working.
    ['pointerdown', 'pointerup', 'mousedown', 'mouseup', 'dblclick', 'contextmenu'].forEach(function (eventName) {
      svg.addEventListener(eventName, function (evt) {
        if (isStatusLegendElement(evt.target)) {
          evt.preventDefault();
          evt.stopImmediatePropagation();
        }
      }, true);
    });

    svg.addEventListener('click', handleSvgClick, true);

    svg.addEventListener('keydown', function (evt) {
      if (evt.key !== 'Enter' && evt.key !== ' ') return;
      var site = findSiteElement(evt.target);
      if (site) showSitePopup(site, evt);
    }, true);

    // Covers markers added or re-rendered after the SVG is loaded by Asset Intellect/PI Vision.
    if (window.MutationObserver) {
      var observer = new MutationObserver(function () { makeSitesClickable(); });
      observer.observe(svg, { childList: true, subtree: true, attributes: true, attributeFilter: ['id', 'class'] });
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
